package com.aoo.bcg.poker;import com.aoo.bcg.gamespi.*;import com.aoo.bcg.gamespi.time.*;import java.util.*;final class LhzpSession implements AuthoritativeGameSession{enum Phase{WAITING,PLAYING,FINISHED}private final long room,owner;private final RulePayload rules;private final Map<Integer,Long>players=new LinkedHashMap<>();private final Set<Integer>ready=new LinkedHashSet<>();private final Map<Integer,List<Integer>>hands=new LinkedHashMap<>();private final Map<Integer,Long>points=new LinkedHashMap<>();private final List<Object>events=new ArrayList<>();private final OperationDeadlineArbiter arbiter=new OperationDeadlineArbiter();private Phase phase=Phase.WAITING;private LhzpRules.Play lead;private int current,leader=-1,passCount,winner=-1;private long sequence,version;LhzpSession(long r,long o,RulePayload x){if(r<=0||o<=0)throw new IllegalArgumentException("invalid LHZP room");room=r;owner=o;rules=x==null?RulePayload.empty():x;players.put(0,o);}public synchronized GameCommandResult execute(GameCommandRequest r){if(r.roomId()!=room||r.sequence()<=sequence)throw new IllegalArgumentException("invalid LHZP command order");long u=Long.parseLong(r.authenticatedUserId());String a=String.valueOf(r.body().asMap().getOrDefault("action","state"));boolean change=true;switch(a){case"state","CLHZPGetRoomInfo"->{participant(u);change=false;}case"join","CLHZPEnterRoom"->join(r.seatId(),u);case"ready","CLHZPReadyRoom"->{own(r.seatId(),u);waiting();ready.add(r.seatId());}case"start","CLHZPStartGame"->start(u);case"operation","CLHZPOpCard"->operate(r,u);default->throw new IllegalArgumentException("unsupported LHZP action");}sequence=r.sequence();if(change){version++;events.add(Map.of("version",version,"after",snapshot()));}return new GameCommandResult("poker.lhzp.response",r.requestId(),viewFor(u));}private void join(int s,long u){waiting();if(s<0||s>=4||players.putIfAbsent(s,u)!=null)throw new IllegalStateException("invalid LHZP seat");}private void start(long u){if(u!=owner)throw new SecurityException("owner only");waiting();if(players.size()<2||!ready.containsAll(players.keySet().stream().filter(x->x!=0).toList()))throw new IllegalStateException("not ready");List<Integer>d=new ArrayList<>(LhzpRules.deck(false));Collections.shuffle(d,new Random(room));int count=d.size()/players.size();for(int s:players.keySet()){List<Integer>h=new ArrayList<>();for(int i=0;i<count;i++)h.add(d.removeFirst());hands.put(s,h);points.put(s,0L);}current=0;phase=Phase.PLAYING;}private void operate(GameCommandRequest r,long u){own(r.seatId(),u);if(phase!=Phase.PLAYING||r.seatId()!=current)throw new IllegalStateException("not LHZP turn");Map<String,Object>p=map(r.body().asMap().getOrDefault("payload",Map.of()));String op=String.valueOf(p.getOrDefault("operation","PASS"));if(op.equals("PASS")){if(lead==null||leader==r.seatId())throw new IllegalStateException("cannot pass");if(++passCount>=players.size()-1){current=leader;lead=null;passCount=0;}else rotate();return;}if(!op.equals("OUT"))throw new IllegalArgumentException("LHZP OUT/PASS required");LhzpRules.Play play=LhzpRules.classify(LhzpRules.Type.valueOf(String.valueOf(p.get("type"))),ints(p.get("cards")));if(!LhzpRules.beats(play,lead))throw new IllegalStateException("play does not beat lead");List<Integer>left=new ArrayList<>(hands.get(r.seatId()));for(int c:play.cards())if(!left.remove(Integer.valueOf(c)))throw new IllegalArgumentException("card not held");hands.put(r.seatId(),left);lead=play;leader=r.seatId();passCount=0;points.merge(r.seatId(),play.cards().stream().mapToLong(LhzpRules::point510k).sum()+LhzpRules.prize(play,bool("redCuo"),bool("blackCuo"),bool("fanCuo")),Long::sum);if(left.isEmpty()){winner=r.seatId();phase=Phase.FINISHED;}else rotate();}private void rotate(){List<Integer>x=new ArrayList<>(players.keySet());current=x.get((x.indexOf(current)+1)%x.size());}public synchronized Map<String,Object>viewFor(long u){Integer mine=seat(u);Map<Integer,Object>s=new LinkedHashMap<>();players.forEach((pos,id)->{List<Integer>h=hands.getOrDefault(pos,List.of());s.put(pos,Map.of("playerId",id,"ready",ready.contains(pos),"cards",Objects.equals(mine,pos)||phase==Phase.FINISHED?h:Collections.nCopies(h.size(),0),"cardCount",h.size(),"point",points.getOrDefault(pos,0L)));});return Map.of("roomId",room,"gameCode","lhzp","phase",phase.name(),"currentSeat",current,"winnerSeat",winner,"seats",Map.copyOf(s),"stateVersion",version);}public synchronized Map<String,Object>authoritativeState(){return snapshot();}public synchronized long stateVersion(){return version;}synchronized List<Object>events(){return List.copyOf(events);}private Map<String,Object>snapshot(){Map<String,Object>x=new LinkedHashMap<>();x.put("schemaVersion",1);x.put("roomId",room);x.put("ownerId",owner);x.put("players",Map.copyOf(players));x.put("ready",List.copyOf(ready));x.put("rules",rules.asMap());x.put("hands",Map.copyOf(hands));x.put("points",Map.copyOf(points));x.put("phase",phase.name());x.put("current",current);x.put("leader",leader);x.put("passCount",passCount);x.put("winner",winner);x.put("sequence",sequence);x.put("stateVersion",version);x.put("lead",lead==null?Map.of():Map.of("type",lead.type().name(),"cards",lead.cards()));return Map.copyOf(x);}static LhzpSession restore(Map<String,Object>s){LhzpSession x=new LhzpSession(lng(s.get("roomId")),lng(s.get("ownerId")),RulePayload.copyOf(map(s.get("rules"))));x.players.clear();map(s.get("players")).forEach((k,v)->x.players.put(Integer.parseInt(k),lng(v)));x.ready.addAll(ints(s.get("ready")));map(s.get("hands")).forEach((k,v)->x.hands.put(Integer.parseInt(k),new ArrayList<>(ints(v))));map(s.get("points")).forEach((k,v)->x.points.put(Integer.parseInt(k),lng(v)));x.phase=Phase.valueOf(String.valueOf(s.get("phase")));x.current=num(s.get("current"));x.leader=num(s.get("leader"));x.passCount=num(s.get("passCount"));x.winner=num(s.get("winner"));x.sequence=lng(s.get("sequence"));x.version=lng(s.get("stateVersion"));Map<String,Object>l=map(s.get("lead"));if(!l.isEmpty())x.lead=LhzpRules.classify(LhzpRules.Type.valueOf(String.valueOf(l.get("type"))),ints(l.get("cards")));return x;}static StatePayload replay(StatePayload base,List<Object>ev){Map<String,Object>s=new LinkedHashMap<>(base.asMap());long v=lng(s.get("stateVersion"));for(Object raw:ev){Map<String,Object>e=map(raw);if(lng(e.get("version"))!=++v)throw new IllegalArgumentException("LHZP replay gap");s=new LinkedHashMap<>(map(e.get("after")));}return StatePayload.copyOf(s);}public OperationDeadline operationDeadline(){return OperationDeadline.none();}public OperationDeadlineArbiter deadlineArbiter(){return arbiter;}public List<String>invariantViolations(){int count=hands.values().stream().mapToInt(List::size).sum();return count<=52?List.of():List.of("CARD_CONSERVATION");}public SettlementPayload settlement(int round,String pv){if(phase!=Phase.FINISHED)throw new IllegalStateException("not finished");long base=bool("qiHu2")?2:1,mult=num(rules.asMap().getOrDefault("multiplier",1));Map<Long,Long>d=new LinkedHashMap<>();players.forEach((s,p)->d.put(p,s==winner?base*mult*(players.size()-1):-base*mult));return new SettlementPayload(room,round,pv,d);}private boolean bool(String k){return Boolean.TRUE.equals(rules.asMap().get(k));}private void waiting(){if(phase!=Phase.WAITING)throw new IllegalStateException("started");}private void own(int s,long u){if(!Long.valueOf(u).equals(players.get(s)))throw new SecurityException("seat not owned");}private void participant(long u){if(!players.containsValue(u))throw new SecurityException("not participant");}private Integer seat(long u){return players.entrySet().stream().filter(e->e.getValue()==u).map(Map.Entry::getKey).findFirst().orElse(null);}private static int num(Object v){return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));}private static long lng(Object v){return v instanceof Number n?n.longValue():Long.parseLong(String.valueOf(v));}private static List<Integer>ints(Object v){return((Collection<?>)v).stream().map(LhzpSession::num).toList();}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object v){Map<String,Object>x=new LinkedHashMap<>();((Map<?,?>)v).forEach((k,n)->x.put(String.valueOf(k),n));return x;}}
